    "videochamada.testimonial_quote": "Nunca había hecho una sesión espiritual antes. Tenía miedo de escuchar cosas malas. Pero ATB me recibió con tanta dulzura... Lloré, pero fue un llanto de alivio. Por fin alguien que entendió lo que yo estaba sintiendo.",
