    "videochamada.h1_line2": "und hörst alles, was die Karten",
    "videochamada.h1_line3": "über dein Leben zu sagen haben",
    "videochamada.hero_desc_1": "Keine schnelle Antwort. Kein Text auf dem Bildschirm.",
    "videochamada.hero_desc_2": "Eine ganze Sitzung, nur für dich, live — du erzählst mir, was auf deinem Herzen liegt, und ich nehme es zu den Karten, ohne Eile.",
