    "videochamada.step2_desc": "Ich lege die Karten direkt für dich und erkläre jede mit Ruhe und Klarheit, so wie du es verdient hast zu verstehen.",
    "videochamada.step3_title": "Du gehst mit einem Weg nach vorn",
    "videochamada.step3_desc": "Nicht nur Vorhersagen — du erhältst praktische und spirituelle Hinweise für deine nächsten Schritte.",
    "videochamada.step4_title": "Alles über Zoom oder Google Meet, bequem von zuhause",
    "videochamada.step4_desc": "Kein Verlassen des Hauses, kein technischer Aufwand. So einfach wie ein Videoanruf mit einer Freundin.",
    "videochamada.testimonial_quote": "Ich hatte noch nie eine spirituelle Sitzung gehabt. Ich hatte Angst, etwas Schlimmes zu hören. Aber ATB hat mich mit so viel Sanftheit empfangen... Ich habe geweint, aber es waren Tränen der Erleichterung. Endlich jemand, der verstanden hat, was ich fühlte.",
    "videochamada.testimonial_author": "— Maria, 58 Jahre, São Paulo",
    "videochamada.for_you_h2": "Diese Sitzung ist für dich, wenn...",
    "videochamada.for_you_1": "Du spürst, dass du an einem Wendepunkt stehst und Klarheit brauchst",
    "videochamada.for_you_2": "Du hast Fragen zu Beziehung, Familie oder deinem nächsten Schritt im Leben",
    "videochamada.for_you_3": "Du möchtest wirklich gehört werden, ohne Eile, von jemandem, der dich wirklich sieht",
    "videochamada.for_you_4": "Du hattest noch nie eine Live-Lesung und wünschst dir ein sicheres, warmes Erlebnis",
    "videochamada.for_you_5": "Du spürst, dass die Antworten nah sind, aber du kannst sie noch nicht sehen",
