    "videochamada.urgency_2": "Wenn die Plätze dieser Woche ausverkauft sind, kommst du auf die Warteliste.",
    "videochamada.faq_h2": "Häufige Fragen",
    "videochamada.faq1_q": "Wie funktioniert es?",
    "videochamada.faq1_a": "Nach der Zahlung schreibt ATB dir innerhalb von 24 Stunden per E-Mail mit einem Zoom- oder Google-Meet-Link und Terminvorschlägen. Die Sitzung dauert etwa eine Stunde, nur für dich.",
    "videochamada.faq2_q": "Ich hatte noch nie eine spirituelle Sitzung. Geht das?",
    "videochamada.faq2_a": "Auf jeden Fall! Viele meiner Klientinnen, die am meisten profitieren, sind genau die, die zum ersten Mal kommen. Ich kümmere mich um alles mit Sorgfalt und ohne Eile.",
